const crypto = require('crypto');
const run = $json.execution || {};
const workflow = $json.workflow || {};
const body = JSON.stringify({ workflow: 'failure_handling', source_workflow: workflow.name || 'unknown', execution_id: run.id || null, error: String(run.error?.message || 'Workflow failed').slice(0,1000) });
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET is not set');
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(body).digest('hex');
const base = $env.JOBPILOT_API_URL || 'http://backend:8000';
return [{json:{body,signature,delivery:'failure-'+(run.id || Date.now()),url:base+'/api/v1/automation/webhooks/failure_handling'}}];
